public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    long N = sc.nextLong();
    long maxPalindromicCube = 0;

    for (long x = 1; x * x * x <= N; x++) {
        long K = x * x * x;

        String S = Long.toString(K);
        int L = S.length();
        boolean isPalindrome = true;

        for (int j = 0; j < L / 2; j++) {
            if (S.charAt(j) != S.charAt(L - j - 1)) {
                isPalindrome = false;
                break;
            }
        }

        if (isPalindrome && K > maxPalindromicCube) {
            maxPalindromicCube = K;
        }
    }

    System.out.println(maxPalindromicCube);
    sc.close();
}
